110	  constructor(options, fn) {
111	    checkOptions(options, fn);
112	    const { delimiter = ',', header = false, skipEmptyLines = false } = options;
113	    this.delimiter = checkDelimiter(delimiter, fn);
114	    this.header = checkBoolean(header, 'header', fn);
115	    this.skipEmptyLines = checkBoolean(skipEmptyLines, 'skipEmptyLines', fn);
116	
117	    this.columns = null; // header names, once the header record has been read
118	    this.seen = this.header ? new Set() : null; // non-null only while reading the header record
