120	    this.state = RECORD_START;
121	    this.started = false; // whether any input has arrived, for the BOM check
122	    this.afterCR = false; // the last character read was a CR, so an LF now completes a CRLF
123	    this.line = 1; // position of the next character to read
124	    this.column = 1;
125	    this.recordLine = 1; // line where the current record starts
126	    this.fieldLine = 1; // position where the current field starts
127	    this.fieldColumn = 1;
128	    this.field = '';
129	    this.record = [];
