137	    if (!this.started && n > 0) {
138	      this.started = true;
139	      if (chunk.charCodeAt(0) === BOM) i = 1;
140	    }
141	    while (i < n) {
142	      const c = chunk.charCodeAt(i);
143	      switch (this.state) {
144	        case RECORD_START:
145	          if (this.afterCR) {
146	            this.afterCR = false;
147	            if (c === LF) {
148	              // Second half of a CRLF that has already ended the previous line.
149	              i++;
150	              break;
151	            }
152	          }
153	          if (this.skipEmptyLines && (c === CR || c === LF)) {
154	            this.lineBreak(c);
155	            i++;
156	            break;
157	          }
158	          this.recordLine = this.line;
159	          this.fieldLine = this.line;
160	          this.fieldColumn = this.column;
161	          this.state = FIELD_START;
162	        // falls through
163	        case FIELD_START:
164	          if (c === QUOTE) {
