302	/**
303	 * Parses CSV text.
304	 *
305	 * @param {string} text
306	 * @param {ParseOptions} [options]
307	 * @returns {Array<string[] | Record<string, string>>} Arrays of fields, or objects keyed by
308	 *   column name when `options.header` is true.
309	 * @throws {TypeError} If `text` is not a string or an option is invalid.
310	 * @throws {CsvError} If the input is malformed.
311	 */
312	function parse(text, options = {}) {
313	  if (typeof text !== 'string') {
314	    throw new TypeError(`parse: text must be a string, got ${describe(text)}`);
315	  }
316	  const parser = new Parser(options, 'parse');
317	  const records = [];
318	  parser.feed(text, records);
319	  parser.finish(records);
320	  return records;
321	}
322	
323	/**
324	 * Creates a streaming parser. Chunks may split the input anywhere; the records
325	 * and errors are the same as `parse` gives for the concatenated input.
326	 * Once `end()` has been called or either method has thrown, both methods throw.
327	 *
328	 * @param {ParseOptions} [options]
329	 * @returns {{ write(chunk: string): Array<string[] | Record<string, string>>,
330	 *             end(): Array<string[] | Record<string, string>> }}
331	 *   `write` returns the records whose terminating line break is in `chunk`;
332	 *   `end` returns the last record, if the input does not end with a line break.
333	 * @throws {TypeError} If an option is invalid.
334	 */
335	function createParser(options = {}) {
336	  const parser = new Parser(options, 'createParser');
337	  let closed = false;
338	
339	  function assertOpen(method) {
340	    if (closed) {
341	      throw new Error(`${method}: the parser has already ended or failed; create a new parser`);
342	    }
343	  }
344	
345	  return {
346	    write(chunk) {
347	      assertOpen('write');
348	      try {
349	        if (typeof chunk !== 'string') {
350	          throw new TypeError(`write: chunk must be a string, got ${describe(chunk)}`);
351	        }
352	        const records = [];
353	        parser.feed(chunk, records);
354	        return records;
355	      } catch (err) {
356	        closed = true;
357	        throw err;
358	      }
359	    },
360	    end() {
361	      assertOpen('end');
362	      closed = true;
363	      const records = [];
364	      parser.finish(records);
365	      return records;
366	    },
367	  };
368	}
369	
370	function fieldText(value, row, index) {
371	  if (typeof value === 'string') return value;
372	  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
373	  if (value === null || value === undefined) return '';
374	  throw new TypeError(
375	    `stringify: rows[${row}] field ${index} must be a string, number, boolean, null or undefined, got ${describe(value)}`,
376	  );
377	}
378	
379	function needsQuotes(text, delimiter) {
380	  const n = text.length;
381	  if (n === 0) return false;
382	  if (text.charCodeAt(0) === SPACE || text.charCodeAt(n - 1) === SPACE) return true;
383	  for (let k = 0; k < n; k++) {
384	    const c = text.charCodeAt(k);
385	    if (c === delimiter || c === QUOTE || c === CR || c === LF) return true;
386	  }
387	  return false;
388	}
389	
390	function quote(text) {
391	  return `"${text.replace(/"/g, '""')}"`;
392	}
393	
394	function formatRecord(values, delimiter, row, atStart) {
395	  const fields = new Array(values.length);
396	  for (let k = 0; k < values.length; k++) {
397	    const text = fieldText(values[k], row, k);
398	    fields[k] = needsQuotes(text, delimiter) ? quote(text) : text;
399	  }
400	  // Unquoted, a lone empty field is an empty line, which skipEmptyLines would drop.
401	  if (fields.length === 1 && fields[0] === '') return '""';
402	  const line = fields.join(String.fromCharCode(delimiter));
403	  // parse drops a BOM at the start of its input, so the output must not begin with one.
404	  if (atStart && line.charCodeAt(0) === BOM) return quote(fields[0]) + line.slice(fields[0].length);
405	  return line;
406	}
407	
408	function rowValues(row, header, index) {
409	  if (Array.isArray(row)) return row;
410	  if (header !== null && row !== null && typeof row === 'object') {
411	    return header.map((name) => (Object.hasOwn(row, name) ? row[name] : undefined));
412	  }
413	  throw new TypeError(
414	    `stringify: rows[${index}] must be an array${header !== null ? ' or an object' : ''}, got ${describe(row)}`,
415	  );
416	}
417	
418	/**
419	 * Serializes records to CSV text that `parse` reads back unchanged.
420	 *
421	 * @param {Array<unknown[] | Record<string, unknown>>} rows Arrays of values, or objects when
422	 *   `options.header` is given. Values may be strings, numbers, booleans, null or undefined.
423	 * @param {StringifyOptions} [options]
424	 * @returns {string} `''` when there is neither a header nor any rows.
425	 * @throws {TypeError} If `rows`, a row, a value or an option has an unsupported type.
426	 */
427	function stringify(rows, options = {}) {
428	  if (!Array.isArray(rows)) {
429	    throw new TypeError(`stringify: rows must be an array, got ${describe(rows)}`);
430	  }
431	  checkOptions(options, 'stringify');
432	  const { delimiter = ',', eol = '\r\n' } = options;
433	  const delimiterCode = checkDelimiter(delimiter, 'stringify');
434	  if (eol !== '\r\n' && eol !== '\n') {
435	    throw new TypeError(`stringify: options.eol must be "\\r\\n" or "\\n", got ${show(eol)}`);
436	  }
437	  // false and null are accepted as "no header" so one options object can be shared with parse.
438	  const header = options.header === undefined || options.header === false ? null : options.header;
439	  if (header !== null) {
440	    if (!Array.isArray(header)) {
441	      throw new TypeError(`stringify: options.header must be an array of strings, got ${describe(header)}`);
442	    }
443	    for (let k = 0; k < header.length; k++) {
444	      if (typeof header[k] !== 'string') {
445	        throw new TypeError(`stringify: options.header[${k}] must be a string, got ${describe(header[k])}`);
446	      }
447	    }
448	  }
449	
450	  const lines = [];
451	  if (header !== null) lines.push(formatRecord(header, delimiterCode, 'header', true));
452	  for (let r = 0; r < rows.length; r++) {
453	    lines.push(formatRecord(rowValues(rows[r], header, r), delimiterCode, r, lines.length === 0));
454	  }
455	  return lines.length === 0 ? '' : lines.join(eol) + eol;
456	}
457	
458	module.exports = { parse, createParser, stringify, CsvError };
