'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { parse, createParser, CsvError } = require('../src/csv');

function parseInChunks(chunks, options) {
  const parser = createParser(options);
  const records = [];
  for (const chunk of chunks) records.push(...parser.write(chunk));
  records.push(...parser.end());
  return records;
}

// Runs fn and returns what it produced or a comparable summary of what it threw.
function outcome(fn) {
  try {
    return { records: fn() };
  } catch (err) {
    return { error: { type: err.constructor.name, message: err.message, line: err.line, column: err.column } };
  }
}

// Every way to cut text into two and three pieces, one piece per code unit, and with empty chunks mixed in.
function* splits(text) {
  const n = text.length;
  for (let i = 0; i <= n; i++) {
    yield [text.slice(0, i), text.slice(i)];
    for (let j = i; j <= n; j++) yield [text.slice(0, i), text.slice(i, j), text.slice(j)];
  }
  yield [...text];
  yield ['', ...[...text].flatMap((c) => [c, ''])];
}

describe('createParser: write and end', () => {
  it('returns each record from the write call whose chunk contains its line break', () => {
    const parser = createParser();
    assert.deepEqual(parser.write('a,b\nc'), [['a', 'b']]);
    assert.deepEqual(parser.write(',d'), []);
    assert.deepEqual(parser.write('\ne\nf'), [['c', 'd'], ['e']]);
    assert.deepEqual(parser.end(), [['f']]);
  });

  it('returns a record as soon as a CR ends it, then skips the LF of the CRLF', () => {
    const parser = createParser();
    assert.deepEqual(parser.write('a\r'), [['a']]);
    assert.deepEqual(parser.write('\nb\r'), [['b']]);
    assert.deepEqual(parser.write('\r'), [['']]);
    assert.deepEqual(parser.end(), []);
  });

  it('returns [] from end when the input is empty or ends with a line break', () => {
    assert.deepEqual(createParser().end(), []);
    const parser = createParser();
    assert.deepEqual(parser.write('a\n'), [['a']]);
    assert.deepEqual(parser.end(), []);
  });

  it('does not return the header record in header mode', () => {
    const parser = createParser({ header: true });
    assert.deepEqual(parser.write('a,b\n'), []);
    assert.deepEqual(parser.write('1,2\n3,'), [{ a: '1', b: '2' }]);
    assert.deepEqual(parser.end(), [{ a: '3', b: '' }]);
  });

  it('ignores a BOM only at the start of the input, even after empty chunks', () => {
    const first = createParser();
    first.write('');
    assert.deepEqual(first.write('﻿a\n'), [['a']]);

    const later = createParser();
    later.write('a\n');
    assert.deepEqual(later.write('﻿b\n'), [['﻿b']]);
  });

  it('keeps separate state for each parser', () => {
    const one = createParser();
    const two = createParser({ delimiter: ';' });
    one.write('"a,');
    two.write('x;');
    assert.deepEqual(one.write('b"\n'), [['a,b']]);
    assert.deepEqual(two.write('y,z\n'), [['x', 'y,z']]);
  });
});

describe('createParser: errors and closing', () => {
  const closedError = (err) => err.constructor === Error && /already ended or failed/.test(err.message);

  it('throws TypeError for invalid options when created', () => {
    assert.throws(() => createParser({ delimiter: '"' }), TypeError);
    assert.throws(() => createParser({ skipEmptyLines: 'yes' }), TypeError);
    assert.throws(() => createParser(null), TypeError);
  });

  it('throws TypeError when a chunk is not a string, then refuses further calls', () => {
    const parser = createParser();
    assert.throws(() => parser.write(Buffer.from('a')), TypeError);
    assert.throws(() => parser.write('a'), closedError);
    assert.throws(() => parser.end(), closedError);
  });

  it('refuses further calls after end', () => {
    const parser = createParser();
    parser.write('a');
    parser.end();
    assert.throws(() => parser.end(), closedError);
    assert.throws(() => parser.write('b'), closedError);
  });

  it('refuses further calls after write throws a CsvError', () => {
    const parser = createParser();
    assert.throws(() => parser.write('"a"b'), CsvError);
    assert.throws(() => parser.write('\n'), closedError);
    assert.throws(() => parser.end(), closedError);
  });

  it('refuses further calls after end throws a CsvError', () => {
    const parser = createParser();
    parser.write('"a');
    assert.throws(() => parser.end(), CsvError);
    assert.throws(() => parser.end(), closedError);
    assert.throws(() => parser.write('"'), closedError);
  });
});

describe('createParser: matches parse wherever the chunks split the input', () => {
  const cases = [
    ['a,b\r\nc,d\r\n', {}],
    ['"a,b","c""d"\r\n"e\r\nf",g\rh\n', {}],
    ['﻿"x",y\n\n\r\n\rz', {}],
    ['\n\r\n\ra\r\n\r\n""\r', { skipEmptyLines: true }],
    ['a;"b;c"\r\n"é😀";\n', { delimiter: ';' }],
    ['k,v\r\n1,"x\r\ny"\r\n\r\n2,z', { header: true, skipEmptyLines: true }],
    ['a,"b\r\nc', {}],
    ['x\r\n"a\r\nb"c', {}],
    ['"a""b"c', {}],
    ['a,b,a\r\n', { header: true }],
    ['a,b\r\n1\r\n', { header: true }],
    ['a,b\r\n1,2,3\r\n"x', { header: true }],
  ];

  for (const [text, options] of cases) {
    it(`${JSON.stringify(text)} ${JSON.stringify(options)}`, () => {
      const expected = outcome(() => parse(text, options));
      for (const chunks of splits(text)) {
        assert.deepEqual(outcome(() => parseInChunks(chunks, options)), expected, JSON.stringify(chunks));
      }
    });
  }
});

describe('createParser: cost', () => {
  it('reads a large input one code unit per write in linear time', { timeout: 10_000 }, () => {
    const field = 'x"'.repeat(100_000);
    const text = `"${field.replace(/"/g, '""')}"\r\n${'a,b\r\n'.repeat(20_000)}`;
    const parser = createParser();
    let count = 0;
    let first;
    for (let i = 0; i < text.length; i++) {
      for (const record of parser.write(text[i])) {
        if (count === 0) first = record;
        count++;
      }
    }
    parser.end();
    assert.equal(count, 20_001);
    assert.equal(first[0], field);
  });
});

