'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { parse, CsvError } = require('../src/csv');

function assertCsvError(fn, line, column) {
  assert.throws(fn, (err) => {
    assert.ok(err instanceof CsvError, `expected a CsvError, got ${err}`);
    assert.deepEqual({ line: err.line, column: err.column }, { line, column });
    return true;
  });
}

describe('parse: arguments', () => {
  it('throws TypeError when text is not a string', () => {
    for (const text of [undefined, null, 1, Buffer.from('a'), ['a'], {}]) {
      assert.throws(() => parse(text), TypeError, `text: ${String(text)}`);
    }
  });

  it('returns [] for an empty string', () => {
    assert.deepEqual(parse(''), []);
    assert.deepEqual(parse('', { header: true }), []);
  });

  it('throws TypeError for a delimiter that is not one character other than ", CR and LF', () => {
    for (const delimiter of ['', ',,', '"', '\r', '\n', '\r\n', 1, null]) {
      assert.throws(() => parse('a', { delimiter }), TypeError, `delimiter: ${JSON.stringify(delimiter)}`);
    }
  });

  it('throws TypeError for options that are not an object or flags that are not booleans', () => {
    assert.throws(() => parse('a', null), TypeError);
    assert.throws(() => parse('a', 'header'), TypeError);
    assert.throws(() => parse('a', { header: 'true' }), TypeError);
    assert.throws(() => parse('a', { header: ['a'] }), TypeError);
    assert.throws(() => parse('a', { skipEmptyLines: 1 }), TypeError);
  });

