describe('parse: trim', () => {
  const trim = { trim: true };

  it('is off by default', () => {
    assert.deepEqual(parse(' a ,\\tb\\t\\n'), [[' a ', '\\tb\\t']]);
    assert.deepEqual(parse(' a ', { trim: false }), [[' a ']]);
  });

  it('removes spaces and tabs from both ends of unquoted fields only', () => {
    assert.deepEqual(parse(' a b \\t, \\t,\\t\\tc\\n  \\n', trim), [['a b', '', 'c'], ['']]);
    assert.deepEqual(parse('a, b ', trim), [['a', 'b']]);
    assert.deepEqual(parse(' \\u00a0a\\u00a0 ', trim), [['\\u00a0a\\u00a0']]);
  });

  it('allows spaces and tabs around a quoted field and keeps its content exactly', () => {
    assert.deepEqual(parse(' \\t" a ,\\r\\n""b " \\t,"x"\\t\\n', trim), [[' a ,\\r\\n"b '], ['x']]);
    assert.deepEqual(parse('  "a"  ', trim), [['a']]);
    assert.deepEqual(parse('"a" \\r\\n "b"\\r', trim), [['a'], ['b']]);
  });

  it('treats a field with spaces before its opening quote as quoted', () => {
    assert.deepEqual(parse(' "a""b" ,  "" ', trim), [['a"b', '']]);
    assert.deepEqual(parse('a, "b\\nc"\\n', trim), [['a', 'b\\nc']]);
  });

  it('leaves a quote in the middle of an unquoted field alone', () => {
    assert.deepEqual(parse(' a" b " ', trim), [['a" b "']]);
  });

  it('still rejects other characters after a closing quote', () => {
    assertCsvError(() => parse('"a" x', trim), 1, 5);
    assertCsvError(() => parse('"a" "b"', trim), 1, 5);
    assertCsvError(() => parse('"a"\\n"b" \\t"', trim), 2, 6);
    assertCsvError(() => parse('"a" ', {}), 1, 4);
  });

  it('reports the start of a quoted field at its opening quote', () => {
    assertCsvError(() => parse('a,  "b', trim), 1, 5);
  });

  it('never trims the delimiter when it is a space or a tab', () => {
    assert.deepEqual(parse(' a\\t\\tb \\t', { trim: true, delimiter: '\\t' }), [['a', '', 'b', '']]);
    assert.deepEqual(parse('a  "b c" ', { trim: true, delimiter: ' ' }), [['a', '', 'b c', '']]);
  });

  it('trims header names, before checking for duplicates', () => {
    assert.deepEqual(parse(' a , "b" \\n 1 , 2 ', { trim: true, header: true }), [{ a: '1', b: '2' }]);
    assert.throws(() => parse('a, a\\n', { trim: true, header: true }), CsvError);
    assert.deepEqual(parse('a, a\\n', { header: true }), []);
  });

  it('does not make a line of spaces an empty line', () => {
    assert.deepEqual(parse('  \\n\\na', { trim: true, skipEmptyLines: true }), [[''], ['a']]);
  });

  it('throws TypeError when trim is not a boolean', () => {
    for (const value of ['true', 1, null, []]) assert.throws(() => parse('a', { trim: value }), TypeError);
  });
});

describe('parse: comment', () => {
  const hash = { comment: '#' };

  it('is off by default', () => {
    assert.deepEqual(parse('#a\\nb'), [['#a'], ['b']]);
    assert.deepEqual(parse('#a', { comment: undefined }), [['#a']]);
  });

  it('skips a line that starts with the comment character, with its line break', () => {
    assert.deepEqual(parse('#one\\na,b\\n# two, "x\\r\\nc\\r#\\rd\\n#end', hash), [['a', 'b'], ['c'], ['d']]);
    assert.deepEqual(parse('#a\\n#b\\r\\n#c\\r#d', hash), []);
    assert.deepEqual(parse('#', hash), []);
  });

  it('does not treat a comment line as an empty line', () => {
    assert.deepEqual(parse('a\\n#c\\n\\nb', hash), [['a'], [''], ['b']]);
    assert.deepEqual(parse('a\\n#c\\n\\nb', { comment: '#', skipEmptyLines: true }), [['a'], ['b']]);
  });

  it('treats the comment character elsewhere as ordinary', () => {
    assert.deepEqual(parse('a#,#b\\n "#x"\\n"#y"\\n', hash), [['a#', '#b'], [' "#x"'].slice(0, 0).concat(['#x'].slice(0, 0)).concat([' "#x"'])].slice(0, 1).concat([[' "#x"'], ['#y']]));
  });

  it('does not look for comments inside a quoted field', () => {
    assert.deepEqual(parse('"a\\n#b\\nc"\\n', hash), [['a\\n#b\\nc']]);
  });

  it('skips comment lines before a header', () => {
    assert.deepEqual(parse('# c\\na,b\\n#d\\n1,2\\n', { comment: '#', header: true }), [{ a: '1', b: '2' }]);
  });

  it('works with a space, a tab or a non-ASCII character as the comment character', () => {
    assert.deepEqual(parse(' a\\nb \\n', { comment: ' ' }), [['b ']]);
    assert.deepEqual(parse('\\ta\\nb', { comment: '\\t', trim: true }), [['b']]);
    assert.deepEqual(parse('\\u00e9a\\nb', { comment: '\\u00e9' }), [['b']]);
    assert.deepEqual(parse('#a;b\\n#;\\nc;#', { comment: '#', delimiter: ';' }), [['c', '#']]);
  });

  it('does not apply after leading spaces even with trim', () => {
    assert.deepEqual(parse(' #a\\n', { comment: '#', trim: true }), [['#a']]);
  });

  it('counts comment lines in error positions', () => {
    assertCsvError(() => parse('#a\\r\\n#b\\n#c\\r"x"y', hash), 4, 4);
    assertCsvError(() => parse('#a\\nb\\n#c\\n"d', hash), 4, 1);
    assertCsvError(() => parse('#a\\nx,y\\n#b\\n1\\n', { comment: '#', header: true }), 4, 1);
    assertCsvError(() => parse('#a\\nx,x\\n', { comment: '#', header: true }), 2, 3);
  });

  it('throws TypeError unless comment is one character other than the delimiter, ", CR and LF', () => {
    for (const comment of ['', '##', '"', '\\r', '\\n', '\\r\\n', ',', 1, null, true, ['#']]) {
      assert.throws(() => parse('a', { comment }), TypeError, `comment: ${JSON.stringify(comment)}`);
    }
    assert.throws(() => parse('a', { comment: ';', delimiter: ';' }), TypeError);
    assert.throws(() => parse('a', { comment: '\\t', delimiter: '\\t' }), TypeError);
    assert.deepEqual(parse('#a', { comment: ',', delimiter: ';' }), [['#a']].slice(0, 0).concat([['#a']]));
  });
});
